<template><div class="backdrop" @click.self="$emit('close')"><form class="modal" @submit.prevent="submit"><header><span>◆</span><h2>{{ category ? 'Modifier la catégorie' : 'Ajouter une nouvelle catégorie' }}</h2><button type="button" @click="$emit('close')">×</button></header><label>Nom de la catégorie <b>*</b><input v-model.trim="form.name" required placeholder="Ex. Plomberie, Climatisation…"></label><label>Description <b>*</b><textarea v-model.trim="form.description" required maxlength="500" placeholder="Décrivez brièvement les types de pannes ou services de cette catégorie…"></textarea></label><small>{{ form.description.length }}/500</small><label>Photo de la catégorie <b v-if="!category">*</b><input accept="image/jpeg,image/png,image/webp" type="file" :required="!category && !form.photo" @change="choisirPhoto"></label><img v-if="preview" class="preview" :src="preview" alt="Aperçu de la catégorie"><div class="status"><strong>Statut</strong><label class="toggle"><input v-model="form.active" type="checkbox"><span></span>{{ form.active ? 'Active' : 'Inactive' }}</label></div><footer><button type="button" class="cancel" @click="$emit('close')">Annuler</button><button class="save">▣ Enregistrer</button></footer></form></div></template>
<script setup>import { reactive, ref, watch } from 'vue';const props=defineProps({category:{type:Object,default:null}});const emit=defineEmits(['close','save']);const form=reactive({name:'',description:'',active:true,photo:null});const preview=ref('');watch(()=>props.category,(value)=>{Object.assign(form,value?{name:value.name,description:value.description,active:value.active,photo:null}:{name:'',description:'',active:true,photo:null});preview.value=value?.photo||''},{immediate:true});function choisirPhoto(event){const file=event.target.files?.[0];if(file){form.photo=file;preview.value=URL.createObjectURL(file)}}function submit(){emit('save',{...form})}</script>
<style scoped>.backdrop{position:fixed;inset:0;z-index:20;display:grid;place-items:center;background:#09285342;padding:18px}.modal{width:min(436px,100%);background:#fff;border-radius:12px;box-shadow:0 20px 45px #07235640;padding:16px}.modal header{display:flex;align-items:center;gap:12px}.modal header>span{display:grid;place-items:center;width:36px;height:36px;border-radius:8px;background:#087f70;color:#fff;font-size:21px}.modal h2{font-size:17px;flex:1;margin:0;color:#072a69}.modal header button{background:transparent;font-size:27px;color:#087f70}.modal>label{display:block;margin-top:18px;font-size:13px;font-weight:800;color:#092d6c}.modal b{color:#fa3750}.modal input:not([type=checkbox]),textarea{display:block;width:100%;margin-top:7px;border:1px solid #bed8ff;border-radius:8px;padding:10px;font:inherit;font-size:12px;outline-color:#087f70}textarea{height:80px;resize:vertical}.modal>small{display:block;text-align:right;color:#6381b5;font-size:10px;margin-top:-17px;padding-right:7px}.status{margin-top:18px;font-size:13px;color:#092d6c}.status strong{display:block;margin-bottom:8px}.toggle{display:flex;align-items:center;gap:9px;color:#174487;font-size:12px}.toggle input{display:none}.toggle span{width:41px;height:23px;border-radius:15px;background:#b9c9df;position:relative}.toggle span:after{content:'';position:absolute;width:17px;height:17px;background:#fff;border-radius:50%;top:3px;left:3px;transition:.2s}.toggle input:checked+span{background:#087f70}.toggle input:checked+span:after{left:21px}footer{display:flex;justify-content:flex-end;gap:12px;border-top:1px solid #e7eff9;margin:20px -16px -16px;padding:14px 16px}.cancel,.save{padding:10px 15px;border-radius:7px;font-size:12px}.cancel{background:#fff;border:1px solid #c9dcf6;color:#436391}.save{background:#087f70;color:#fff}</style>
